<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\{CcsHumanRules,CcsRuleGuard,CcsAdministration,CcsInvoiceCancellation};
class CcsHumanRulesController extends Controller{
private function staff(Request $r):void{abort_unless(($r->user()->ccs_active??false)&&in_array(app(CcsAdministration::class)->role($r->user()),['owner','cashier'],true),403);}
public function index(Request $r){$this->staff($r);$owner=app(CcsHumanRules::class)->owner($r->user());$approvals=DB::table('ccs_rule_approvals')->when(!$owner,fn($q)=>$q->where('requested_by',$r->user()->id))->orderByDesc('id')->paginate(20);$invoice=$r->filled('invoice_id')?DB::table('invoices')->find((int)$r->input('invoice_id')):null;$payments=$invoice?DB::table('payments')->where('invoice_id',$invoice->id)->where('amount_lkr','>',0)->get():collect();$cancellations=DB::table('ccs_invoice_cancellations as c')->join('invoices as i','i.id','=','c.invoice_id')->select('c.*','i.invoice_number')->orderByDesc('c.id')->limit(30)->get();return view('ccs.human-rules',compact('approvals','owner','cancellations','invoice','payments'));}
public function decision(Request $r,int $id){abort_unless(app(CcsHumanRules::class)->owner($r->user()),403);$d=$r->validate(['decision'=>'required|in:approved,rejected','reason'=>'required|string|min:5|max:1000']);DB::transaction(function()use($r,$id,$d){app(CcsHumanRules::class)->lock();$a=DB::table('ccs_rule_approvals')->where('id',$id)->first();abort_unless($a&&$a->status==='pending',409,'Request already decided.');DB::table('ccs_rule_approvals')->where('id',$id)->update(['status'=>$d['decision'],'decided_by'=>$r->user()->id,'decision_reason'=>$d['reason'],'expires_at'=>$d['decision']==='approved'?now()->addHours(24):null,'updated_at'=>now()]);app(CcsAdministration::class)->audit($r->user()->id,'rule_'.$d['decision'],'rule_approval',$id,['reason'=>$d['reason']]);});return back()->with('success','Decision saved. The requesting cashier can retry the same details.');}
public function context(Request $r){$r->validate(['actions'=>'required|array|max:100','actions.*'=>'required|string|max:500']);$out=[];$extras=[];$guard=app(CcsRuleGuard::class);foreach($r->input('actions') as $action){$url=parse_url($action);if(isset($url['host'])&&$url['host']!==$r->getHost())continue;$path=$url['path']??'';if(!preg_match('~^/(?:ccs|t)/~',$path))continue;try{$route=null;foreach(['POST','PUT','PATCH','DELETE'] as $verb){$test=Request::create($r->getSchemeAndHttpHost().$path,$verb);try{$candidate=app('router')->getRoutes()->match($test);$test->setRouteResolver(fn()=>$candidate);if($guard->target($test)){$route=$candidate;break;}}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface){continue;}}if(!$route)continue;$test->setRouteResolver(fn()=>$route);if(!app(CcsAdministration::class)->can($r->user(),$route->getName()??'',$test->method()))continue;$target=$guard->target($test);if($target){$out[$action]=$guard->version($target);if($target[0]==='customers')$extras[$action]=['email'=>DB::table('customers')->where('id',$target[1])->value('email')];}}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface){continue;}}return response()->json(['versions'=>$out,'extras'=>$extras])->header('Cache-Control','no-store');}
public function policy(Request $r){app(\App\Services\CcsCashierRules::class)->save($r);return redirect()->to(route('ccs.settings').'#settings-security')->with('success','Cashier rules saved.');}
public function walkin(Request $r){$this->staff($r);return app(\App\Services\CcsWalkInSale::class)->save($r);}
public function abandoned(Request $r){$this->staff($r);$d=$r->validate(['reason'=>'required|string|min:5|max:500','token'=>'required|uuid']);DB::transaction(function()use($r,$d){app(CcsHumanRules::class)->lock();if(DB::table('ccs_rule_submissions')->where('token',$d['token'])->exists())return;app(CcsAdministration::class)->audit($r->user()->id,'unsaved_sale_cancelled','pos',null,['reason'=>$d['reason']]);DB::table('ccs_rule_submissions')->insert(['token'=>$d['token'],'user_id'=>$r->user()->id,'action'=>'unsaved_sale_cancelled','fingerprint'=>hash('sha256',$d['reason']),'location'=>route('ccs.pos'),'created_at'=>now(),'updated_at'=>now()]);});return response()->json(['saved'=>true]);}
public function reverse(Request $r,int $id){$this->staff($r);app(\App\Services\CcsPaymentReversal::class)->reverse($r,$id);return back()->with('success','Payment reversal recorded. Original payment remains in history.');}
public function cancel(Request $r,int $id){$this->staff($r);$result=app(CcsInvoiceCancellation::class)->cancel($r,$id);return back()->with('success',$result['duplicate']?'Cancellation was already recorded.':'Invoice voided. Recorded refund: Rs. '.number_format($result['refund_lkr'],2).'.');}
}
